public class Main {
    static String grade(int marks) {
        if (marks >= 90) return "A";
        if (marks >= 75) return "B";
        if (marks >= 60) return "C";
        return "F";
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int total = 0;
        for (int i = 0; i < n; i++) {
            String name = sc.next();
            int marks = sc.nextInt();
            total += marks;
            System.out.println(name + ": " + grade(marks));
        }
        System.out.printf(Locale.ROOT, "Average: %.2f%n", (double) total / n);
    }
}

