public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String op = sc.next();
        int n = sc.nextInt();
        int[][] a = new int[n][n], b = new int[n][n];
        for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) a[i][j] = sc.nextInt();
        for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) b[i][j] = sc.nextInt();
        for (int i = 0; i < n; i++) {
            StringBuilder line = new StringBuilder();
            for (int j = 0; j < n; j++) {
                int value = op.equals("add") ? a[i][j] + b[i][j] : 0;
                if (!op.equals("add"))
                    for (int k = 0; k < n; k++) value += a[i][k] * b[k][j];
                if (j > 0) line.append(' ');
                line.append(value);
            }
            System.out.println(line);
        }
    }
}

