import java.util.*;
import java.nio.file.*;
import java.io.IOException;

public class Main {
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        StringBuilder csv = new StringBuilder();
        for (int i = 0; i < n; i++) csv.append(sc.nextLine().trim()).append('\n');
        Path file = Files.createTempFile("scores", ".csv");
        Files.writeString(file, csv.toString());
        List<String> lines = Files.readAllLines(file);
        Files.deleteIfExists(file);
        String best = "";
        int bestScore = -1;
        for (String line : lines) {
            if (line.isBlank()) continue;
            String[] parts = line.split(",");
            int score = Integer.parseInt(parts[1]);
            if (score > bestScore) { bestScore = score; best = parts[0] + ":" + score; }
        }
        System.out.println("rows=" + lines.size());
        System.out.println("max=" + best);
    }
}

