import java.util.*;

public class Main {
    static class Stack<T> {
        private final Deque<T> items = new ArrayDeque<>();
        void push(T item) { items.push(item); }
        T pop() { return items.pop(); }
        T peek() { return items.peek(); }
        int size() { return items.size(); }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Stack<String> stack = new Stack<>();
        while (sc.hasNext()) {
            String cmd = sc.next();
            if (cmd.equals("end")) break;
            if (cmd.equals("push")) stack.push(sc.next());
            else if (cmd.equals("pop")) System.out.println(stack.pop());
            else if (cmd.equals("peek")) System.out.println(stack.peek());
            else if (cmd.equals("size")) System.out.println(stack.size());
        }
    }
}

